// ============================================
// VALIDER LA REQUÊTE — audio-transcription (azy.daily#296)
// ============================================
// Entrée invalide → 400 SYNCHRONE { accepted: false, error } et AUCUN rappel.
// Entrée valide → le 202 part tout de suite, puis :
//   - refus avant appel (durée connue au-delà de la limite du modèle, ou
//     fichier trop gros pour OpenAI) → rappel d'échec sans appel fournisseur ;
//   - Mistral → file_url (l'URL signée), n8n ne télécharge rien ;
//   - OpenAI → téléchargement puis multipart (nœuds HTTP natifs).
// La clé (api_key) ne sort de ce nœud que vers l'en-tête Authorization des
// nœuds HTTP : jamais dans une réponse, un rappel ou un message d'erreur.

const entree = $input.first().json;
const body = entree && entree.body && typeof entree.body === 'object' && !Array.isArray(entree.body) ? entree.body : {};
const erreurs = [];
const champs = [];
const refuser = (champ, message) => { champs.push(champ); erreurs.push(message); };

// whisper-local (azy.daily#421) : moteur faster-whisper de prod001. Option B — le routage
  // vers un fournisseur vit dans n8n, y compris quand il est local. Sa charge est relayée
  // VERBATIM : le moteur expose le contrat #296, pas une interface à lui.
  const PROVIDERS = ['mistralai', 'openai', 'whisper-local'];
// Mesuré (azy.daily#301) : OpenAI plafonne la REQUÊTE à 26 214 400 octets (413),
// enveloppe multipart comprise. On garde une marge pour l'enveloppe.
const OPENAI_PLAFOND_REQUETE = 26214400;
const MARGE_MULTIPART = 16384;
// Mesuré (#301) : gpt-4o-transcribe et son mini refusent au-delà de 1 400 s.
// whisper-1 et voxtral-mini-2602 : 2 h acceptées, aucune limite connue → aucun refus.
const LIMITES_DUREE = [{ motif: /^gpt-4o(-mini)?-transcribe(-\d{4}-\d{2}-\d{2})?$/, secondes: 1400 }];

const texteRequis = nom => {
  const v = body[nom];
  if (typeof v !== 'string' || v.trim() === '') {
    refuser(nom, `${nom} requis (chaîne non vide)`);
    return '';
  }
  return v.trim();
};
const absent = v => v === undefined || v === null || v === '';
const HTTPS = /^https:\/\/[^\s\/?#@]+([\/?#][^\s]*)?$/i;

const jobId = texteRequis('job_id');
const callbackUrl = texteRequis('callback_url');
const audioUrl = texteRequis('audio_url');
const mimeType = texteRequis('mime_type');
const filename = texteRequis('filename');
const provider = texteRequis('provider');
const model = texteRequis('model');
const apiKey = texteRequis('api_key');

// https partout, SAUF vers le réseau local (azy.daily#421) : depuis Garage, chat.api signe
// des URL `http://prod001.local:3900/...` — exiger https refuserait tout job whisper-local,
// et chat.api en dev écoute lui aussi en http sur un nom .local. Mesuré le 2026-09-23.
const HTTP_LOCAL = /^http:\/\/([a-z0-9-]+\.local|localhost|127\.0\.0\.1|192\.168\.\d{1,3}\.\d{1,3})(:\d+)?([\/?#][^\s]*)?$/i;
const urlAcceptable = u => HTTPS.test(u) || HTTP_LOCAL.test(u);
if (callbackUrl && !urlAcceptable(callbackUrl)) refuser('callback_url', 'callback_url doit être https (ou http vers le réseau local)');
if (audioUrl && !urlAcceptable(audioUrl)) refuser('audio_url', 'audio_url doit être https (ou http vers le réseau local)');
if (provider && !PROVIDERS.includes(provider)) {
  refuser('provider', `provider inconnu (${provider.slice(0, 40)}), valeurs acceptées ${PROVIDERS.join(' | ')}`);
}

// size_bytes : FACULTATIF (demande api du 17/09, azy.daily#296) — un document
// ancien sans taille ne doit pas échouer. Présent : entier > 0 (nombre ou chaîne
// de chiffres). Absent : le plafond OpenAI est vérifié après téléchargement
// (content-length, puis taille du binaire) dans « Préparer le fichier OpenAI ».
let sizeBytes = null;
if (!absent(body.size_bytes)) {
  const n = typeof body.size_bytes === 'string' && /^\d+$/.test(body.size_bytes.trim()) ? Number(body.size_bytes) : body.size_bytes;
  if (typeof n !== 'number' || !Number.isInteger(n) || n <= 0) refuser('size_bytes', 'size_bytes doit être un entier positif');
  else sizeBytes = n;
}

// language : facultatif ; transmis tel quel (vide = détection par le fournisseur)
let language = '';
if (!absent(body.language)) {
  if (typeof body.language !== 'string' || body.language.trim() === '' || body.language.trim().length > 16) {
    refuser('language', 'language doit être une chaîne courte (ex. fr)');
  } else {
    language = body.language.trim();
  }
}

// duration_seconds : facultatif ; annoncé par le client, sert au refus avant appel
let durationSeconds = null;
if (!absent(body.duration_seconds)) {
  const n = typeof body.duration_seconds === 'string' && /^\d+(\.\d+)?$/.test(body.duration_seconds.trim())
    ? Number(body.duration_seconds) : body.duration_seconds;
  if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0) refuser('duration_seconds', 'duration_seconds doit être un nombre positif');
  else durationSeconds = n;
}

if (erreurs.length > 0) {
  return [{
    json: {
      valide: false,
      reponse: {
        accepted: false,
        job_id: jobId || null,
        error: { code: 'invalid_request', http_status: 400, message: erreurs.join(' ; '), fields: champs },
      },
    },
  }];
}

// --- Nom de fichier pour OpenAI ---
// Mesuré le 17/09 : OpenAI juge le format sur l'EXTENSION du nom envoyé.
// « parole.ogg » et « parole » passent ; « parole.opus » et « parole.bin » →
// 400 « Invalid file format ». On corrige l'extension d'après mime_type.
const EXT_OPENAI = ['flac', 'm4a', 'mp3', 'mp4', 'mpeg', 'mpga', 'oga', 'ogg', 'wav', 'webm'];
const EXT_PAR_MIME = {
  'audio/ogg': 'ogg', 'audio/opus': 'ogg', 'application/ogg': 'ogg', 'audio/x-ogg': 'ogg',
  'audio/webm': 'webm', 'video/webm': 'webm',
  'audio/mpeg': 'mp3', 'audio/mp3': 'mp3', 'audio/mpga': 'mp3', 'audio/x-mp3': 'mp3',
  'audio/flac': 'flac', 'audio/x-flac': 'flac',
  'audio/mp4': 'm4a', 'audio/m4a': 'm4a', 'audio/x-m4a': 'm4a', 'video/mp4': 'mp4',
  'audio/wav': 'wav', 'audio/x-wav': 'wav', 'audio/wave': 'wav', 'audio/vnd.wave': 'wav',
};
const ALIAS_EXT = { opus: 'ogg' };
const nomPropre = filename.split(/[\\/]/).pop().replace(/["\r\n\t]/g, '_') || 'audio';
const m = nomPropre.match(/^(.*)\.([A-Za-z0-9]{1,5})$/);
const base = m && m[1] ? m[1] : nomPropre;
const ext = m && m[1] ? m[2].toLowerCase() : '';
const extMime = EXT_PAR_MIME[mimeType.toLowerCase().split(';')[0].trim()];
let nomFichier = nomPropre;
if (!EXT_OPENAI.includes(ext)) {
  const cible = ALIAS_EXT[ext] || extMime;
  if (cible) nomFichier = `${base}.${cible}`;
}

// --- Refus avant appel ---
const limite = (LIMITES_DUREE.find(l => l.motif.test(model)) || {}).secondes || null;
let echec = null;
if (limite && durationSeconds !== null && durationSeconds > limite) {
  echec = {
    code: 'audio_too_long',
    http_status: 400,
    provider_message: `Refusé avant appel par n8n — duration_seconds ${durationSeconds} dépasse la durée maximale de ${model} (${limite} s)`,
  };
} else if (provider === 'openai' && sizeBytes !== null && sizeBytes + MARGE_MULTIPART > OPENAI_PLAFOND_REQUETE) {
  echec = {
    code: 'file_too_large',
    http_status: 413,
    provider_message: `Refusé avant appel par n8n — size_bytes ${sizeBytes} plus la marge multipart (${MARGE_MULTIPART}) dépasse le plafond de requête OpenAI (${OPENAI_PLAFOND_REQUETE} octets)`,
  };
}

return [{
  json: {
    valide: true,
    reponse: { accepted: true, job_id: jobId },
    job_id: jobId,
    callback_url: callbackUrl,
    audio_url: audioUrl,
    mime_type: mimeType,
    filename: filename,
    nom_fichier: nomFichier,
    size_bytes: sizeBytes,
    provider: provider,
    model: model,
    api_key: apiKey,
    language: language,
    duration_seconds: durationSeconds,
    limite_duree_s: limite,
    // Mesuré : verbose_json (qui porte duration) n'existe que pour whisper ;
    // gpt-4o-*-transcribe → 400 « not compatible with model ».
    response_format: provider === 'openai' ? (/^whisper/.test(model) ? 'verbose_json' : 'json') : null,
  // Relayée telle quelle au moteur local, y compris provider et api_key ('local', qu'il
  // ignore) : ce que chat.api a composé fait foi, nous ne recomposons rien.
  charge_locale: provider === 'whisper-local' ? body : null,
    echec: echec,
  },
}];

// ============================================
// PRÉPARER LE FICHIER — audio-transcription (azy.daily#296, #421)
// ============================================
// Entrée : la sortie du téléchargement de audio_url (HTTP Request natif,
// responseFormat file + fullResponse + neverError) → json { headers, statusCode },
// binaire dans « data ». En panne réseau / délai : json { error } (onError).
//
// Ce nœud ne TOUCHE PAS aux octets (n8n altère les Buffer passés à
// helpers.httpRequest, et le multipart est construit par le nœud HTTP natif) :
// il ne fait que renommer le binaire « file » et corriger fileName / mimeType
// (OpenAI juge le format sur l'extension du nom — mesuré).
//
// Échec de téléchargement (URL signée expirée 403, 404, panne du stockage) →
// audio_fetch_failed (relançable côté api : le même POST refait une URL signée ;
// azy.daily#296, 17/09). Ni le fichier ni le fournisseur ne sont en cause.
// http_status : celui de la réponse du stockage, null si aucune réponse HTTP.
// Fichier vide au stockage → audio_unreadable : relancer ne le remplira pas.

const req = $('Valider la requête').first().json;
const item = $input.first();
const r = item.json || {};
const bin = item.binary && item.binary.data;

const OPENAI_PLAFOND_REQUETE = 26214400;
const MARGE_MULTIPART = 16384;

const cle = String(req.api_key || '');
const nettoyer = s => {
  let t = String(s === undefined || s === null ? '' : s);
  if (cle.length >= 8) t = t.split(cle).join('[clé masquée]');
  // Une URL signée (audio_url) donne accès au fichier : on masque sa requête.
  t = t.replace(/(https?:\/\/[^\s'"?]+)\?[^\s'"]*/g, '$1?[paramètres masqués]');
  return t.slice(0, 2000);
};
const echec = (code, httpStatus, message) => [{
  json: { job_id: req.job_id, echec: { code: code, http_status: httpStatus, provider_message: nettoyer(message) } },
}];

if (r.error !== undefined && r.statusCode === undefined) {
  const e = r.error && typeof r.error === 'object' ? r.error : { message: String(r.error) };
  const brut = `${e.code || ''} ${e.message || ''}`.trim();
  const delai = /ECONNABORTED|ETIMEDOUT|ESOCKETTIMEDOUT|timeout/i.test(brut);
  return echec('audio_fetch_failed', null,
    `Téléchargement de audio_url impossible (${delai ? 'délai dépassé' : 'erreur réseau'}) — ${brut || 'sans détail'}`);
}

const statut = Number(r.statusCode);
if (!(statut >= 200 && statut < 300)) {
  return echec('audio_fetch_failed', statut >= 100 && statut <= 599 ? statut : null,
    `Téléchargement de audio_url en échec — HTTP ${Number.isFinite(statut) ? statut : '?'} ${r.statusMessage || ''}`.trim());
}
if (!bin) {
  return echec('audio_fetch_failed', statut, 'Téléchargement de audio_url sans contenu binaire');
}

const entetes = r.headers || {};
const longueur = entetes['content-length'];
if (longueur !== undefined && Number(longueur) === 0) {
  return echec('audio_unreadable', statut, 'Téléchargement de audio_url — fichier vide (content-length 0)');
}
const octets = [Number(longueur), Number(bin.bytes)].find(n => Number.isFinite(n) && n > 0) || null;
// Le plafond est celui d'OPENAI (26 Mo par requête, mesuré) — pas une règle universelle.
// Mistral reçoit désormais les octets lui aussi (azy.daily#421), mais son plafond multipart
// n'a PAS été mesuré : on ne refuse donc rien avant appel de son côté, plutôt que d'inventer
// une limite qui rejetterait des fichiers qu'il accepte. Un refus de sa part est traduit par
// « Construire le rappel », comme tout message de fournisseur.
if (req.provider === 'openai' && octets !== null && octets + MARGE_MULTIPART > OPENAI_PLAFOND_REQUETE) {
  return echec('file_too_large', 413,
    `Refusé avant appel par n8n — le fichier téléchargé pèse ${octets} octets, plus la marge multipart (${MARGE_MULTIPART}) le plafond de requête OpenAI (${OPENAI_PLAFOND_REQUETE} octets) est dépassé`);
}

return [{
  json: {
    job_id: req.job_id,
    provider: req.provider,
    model: req.model,
    api_key: req.api_key,
    language: req.language,
    response_format: req.response_format,
    octets_telecharges: octets,
    echec: null,
  },
  binary: {
    file: Object.assign({}, bin, {
      fileName: req.nom_fichier,
      fileExtension: (String(req.nom_fichier).match(/\.([A-Za-z0-9]+)$/) || [])[1],
      mimeType: req.mime_type,
    }),
  },
}];

// ============================================
// CONSTRUIRE LE RAPPEL — audio-transcription (azy.daily#296)
// ============================================
// Reçoit l'une de ces entrées :
//   - { echec: { code, http_status, provider_message } } — refus avant appel
//     (Valider la requête) ou échec de téléchargement (Préparer le fichier OpenAI) ;
//   - la réponse d'un nœud HTTP de transcription en fullResponse + neverError :
//     { statusCode, headers, body } (JSON) ou { statusCode, headers, data } (texte :
//     OpenAI rend son 401 en text/plain — mesuré) ;
//   - { error } quand le nœud HTTP n'a eu AUCUNE réponse (délai, DNS, connexion) :
//     onError=continueRegularOutput n'émet pas de statusCode, le statut éventuel
//     est enfoui dans le message « NNN - {...} ».
// Rend { callback_url, job_id, corps_json } : corps_json est construit UNE fois
// (JSON.stringify), signé tel quel par « Signer le rappel » puis envoyé tel quel.

const req = $('Valider la requête').first().json;
const entree = $input.first().json || {};

// ---------- La clé ne sort jamais ----------
const cle = String(req.api_key || '');
const nettoyerTexte = s => {
  let t = String(s === undefined || s === null ? '' : s);
  if (cle.length >= 8) t = t.split(cle).join('[clé masquée]');
  // Mistral cite l'URL signée dans ses erreurs (« File could not be fetched from
  // url '…?sig=…' ») : la requête d'une URL signée donne accès au fichier.
  t = t.replace(/(https?:\/\/[^\s'"?]+)\?[^\s'"]*/g, '$1?[paramètres masqués]');
  return t;
};
const masquer = v => {
  if (typeof v === 'string') return cle.length >= 8 && v.includes(cle) ? v.split(cle).join('[clé masquée]') : v;
  if (Array.isArray(v)) return v.map(masquer);
  if (v && typeof v === 'object') {
    const o = {};
    for (const k of Object.keys(v)) o[k] = masquer(v[k]);
    return o;
  }
  return v;
};

// ---------- Correspondance erreur fournisseur → liste FERMÉE ----------
// Messages mesurés le 17/09 (voir la PR) :
//   401 Mistral « Invalid API Key » / OpenAI « Incorrect API key provided »  → provider_auth
//   413 OpenAI « Maximum content size limit (26214400) exceeded »            → file_too_large
//   400 OpenAI « Invalid file format. Supported formats … »                  → unsupported_format
//   400 Mistral « Audio input could not be decoded. »                        → audio_unreadable
//   400 OpenAI « audio duration 1500.0 seconds is longer than 1400 seconds … » → audio_too_long
//   400 OpenAI (mini) « Total number of tokens in instructions + audio is too large for this model » → audio_too_long
//   400 OpenAI « Audio file might be corrupted or unsupported » (3 600 s)    → audio_too_long si durée connue > limite, sinon audio_unreadable
//   400 Mistral « File could not be fetched from url '…' »                   → audio_fetch_failed (URL signée inutilisable, relançable)
//   400 Mistral « Invalid model », 404 OpenAI « model_not_found »            → internal_error
// audio_fetch_failed ajouté le 17/09 à la demande de l'api (azy.daily#296).
const CODES = ['file_too_large', 'unsupported_format', 'audio_unreadable', 'audio_too_long', 'provider_unavailable', 'provider_auth', 'audio_fetch_failed', 'internal_error'];
function classer(statut, message) {
  const texte = String(message || '');
  if (statut === 401 || statut === 403) return 'provider_auth';
  if (statut === 413) return 'file_too_large';
  if (!statut || statut === 408 || statut === 429 || statut >= 500) return 'provider_unavailable';
  if (/is longer than \d+(\.\d+)? seconds/i.test(texte) || /audio is too large for this model/i.test(texte)) return 'audio_too_long';
  if (/might be corrupted/i.test(texte)) {
    const limite = Number(req.limite_duree_s);
    const duree = Number(req.duration_seconds);
    return limite > 0 && duree > limite ? 'audio_too_long' : 'audio_unreadable';
  }
  if (/invalid file format|unsupported (file |audio )?format|format (is )?not supported/i.test(texte)) return 'unsupported_format';
  if (/could not be fetched from url/i.test(texte)) return 'audio_fetch_failed';
  if (/could not be decoded|corrupt/i.test(texte)) return 'audio_unreadable';
  return 'internal_error';
}

const analyser = c => {
  if (typeof c !== 'string') return c;
  try {
    const x = JSON.parse(c);
    return typeof x === 'string' ? analyser(x) : x;
  } catch (e) {
    return c;
  }
};
const messageFournisseur = c => {
  if (c === undefined || c === null || c === '') return '';
  if (typeof c === 'string') return c;
  if (c.error && typeof c.error === 'object' && c.error.message) return c.error.message;   // OpenAI
  if (typeof c.error === 'string') return c.error;
  if (typeof c.message === 'string' && c.message) return c.message;                          // Mistral
  if (c.detail !== undefined) return typeof c.detail === 'string' ? c.detail : JSON.stringify(c.detail); // Mistral 401/422
  return JSON.stringify(c);
};

const echec = (code, httpStatus, providerMessage) => ({
  success: false,
  job_id: req.job_id,
  error: {
    code: CODES.includes(code) ? code : 'internal_error',
    http_status: httpStatus,
    provider_message: nettoyerTexte(providerMessage).slice(0, 2000),
  },
});

// ---------- Langue : code ISO 639-1 ----------
// Mesuré : whisper-1 rend le NOM (« french ») ; voxtral-mini-2602 rend null
// même quand language est fourni → on retombe sur la langue demandée.
const NOMS_LANGUES = 'english:en,chinese:zh,mandarin:zh,german:de,spanish:es,castilian:es,russian:ru,korean:ko,french:fr,japanese:ja,portuguese:pt,turkish:tr,polish:pl,catalan:ca,valencian:ca,dutch:nl,flemish:nl,arabic:ar,swedish:sv,italian:it,indonesian:id,hindi:hi,finnish:fi,vietnamese:vi,hebrew:he,ukrainian:uk,greek:el,malay:ms,czech:cs,romanian:ro,moldavian:ro,moldovan:ro,danish:da,hungarian:hu,tamil:ta,norwegian:no,thai:th,urdu:ur,croatian:hr,bulgarian:bg,lithuanian:lt,latin:la,maori:mi,malayalam:ml,welsh:cy,slovak:sk,telugu:te,persian:fa,latvian:lv,bengali:bn,serbian:sr,azerbaijani:az,slovenian:sl,kannada:kn,estonian:et,macedonian:mk,breton:br,basque:eu,icelandic:is,armenian:hy,nepali:ne,mongolian:mn,bosnian:bs,kazakh:kk,albanian:sq,swahili:sw,galician:gl,marathi:mr,punjabi:pa,panjabi:pa,sinhala:si,sinhalese:si,khmer:km,shona:sn,yoruba:yo,somali:so,afrikaans:af,occitan:oc,georgian:ka,belarusian:be,tajik:tg,sindhi:sd,gujarati:gu,amharic:am,yiddish:yi,lao:lo,uzbek:uz,faroese:fo,haitian creole:ht,haitian:ht,pashto:ps,pushto:ps,turkmen:tk,nynorsk:nn,maltese:mt,sanskrit:sa,luxembourgish:lb,letzeburgesch:lb,myanmar:my,burmese:my,tibetan:bo,tagalog:tl,malagasy:mg,assamese:as,tatar:tt,hawaiian:haw,lingala:ln,hausa:ha,bashkir:ba,javanese:jv,sundanese:su,cantonese:yue';
const LANGUES = {};
for (const paire of NOMS_LANGUES.split(',')) {
  const [nom, code] = paire.split(':');
  LANGUES[nom] = code;
}
const normaliserLangue = l => {
  if (typeof l !== 'string' || l.trim() === '') return null;
  const t = l.trim();
  return LANGUES[t.toLowerCase()] || t;
};

// ---------- Lecture de l'entrée ----------
let corps;
if (entree.echec) {
  corps = echec(entree.echec.code, entree.echec.http_status, entree.echec.provider_message);
} else if (entree.error !== undefined && entree.statusCode === undefined) {
  const e = entree.error && typeof entree.error === 'object' ? entree.error : { message: String(entree.error) };
  const brut = String(e.message || '');
  const m = brut.match(/^\s*(\d{3})\s*-\s*([\s\S]*)$/);
  let statut = [e.statusCode, e.status, e.httpCode, e.response && e.response.status]
    .map(Number).find(n => n >= 100 && n <= 599);
  if (!statut && m) statut = parseInt(m[1], 10);
  // n8n remplace le message d'un 429 par un conseil (« Try spacing your requests out… »)
  if (!statut && /Try spacing your requests out/i.test(brut)) statut = 429;
  if (statut) {
    const c = analyser(e.error !== undefined ? e.error : (m ? m[2] : brut));
    const message = messageFournisseur(c) || brut;
    corps = echec(classer(statut, message), statut, message);
  } else {
    const detail = `${e.code || ''} ${brut}`.trim();
    const delai = /ECONNABORTED|ETIMEDOUT|ESOCKETTIMEDOUT|timeout/i.test(detail);
    // http_status null : aucune réponse HTTP n'a existé (contrat §7, pas de 502/504 inventé)
    corps = echec('provider_unavailable', null,
      `Aucune réponse du fournisseur (${delai ? 'délai dépassé' : 'erreur réseau'}) — ${detail || 'sans détail'}`);
  }
} else {
  const statut = Number(entree.statusCode);
  const c = analyser(entree.body !== undefined ? entree.body : entree.data);
  if (!(statut >= 200 && statut < 300)) {
    const message = messageFournisseur(c) || `HTTP ${statut}`;
    const valide = statut >= 100 && statut <= 599;
    corps = echec(classer(valide ? statut : 0, message), valide ? statut : null, message);
  } else if (!c || typeof c !== 'object' || typeof c.text !== 'string') {
    corps = echec('internal_error', statut, `Réponse du fournisseur sans champ text — ${String(JSON.stringify(c)).slice(0, 500)}`);
  } else {
    // Durée DITE PAR LE FOURNISSEUR — c'est ce que l'api facture.
    //   OpenAI : duration (verbose_json), sinon usage { type: "duration", seconds }
    //   Mistral : usage.prompt_audio_seconds (mesuré : entier arrondi par défaut)
    // Aucune → champ OMIS (l'api facture la réservation, usage « estimated »).
    let duree;
    if (req.provider === 'openai') {
      if (typeof c.duration === 'number' && Number.isFinite(c.duration)) duree = c.duration;
      else if (c.usage && c.usage.type === 'duration' && typeof c.usage.seconds === 'number') duree = c.usage.seconds;
    } else if (c.usage && typeof c.usage.prompt_audio_seconds === 'number' && Number.isFinite(c.usage.prompt_audio_seconds)) {
      duree = c.usage.prompt_audio_seconds;
    }
    const usage = {};
    if (duree !== undefined) usage.duration_seconds = duree;
    corps = {
      success: true,
      job_id: req.job_id,
      data: {
        text: c.text,
        language: normaliserLangue(c.language) || normaliserLangue(req.language),
      },
      meta: {
        provider: req.provider,
        model: req.model,
        usage: usage,
      },
    };
  }
}

corps = masquer(corps);

return [{
  json: {
    job_id: req.job_id,
    callback_url: req.callback_url,
    corps_json: JSON.stringify(corps),
  },
}];

// ============================================================
// CONSTRUIRE LE RAPPEL D'ÉCHEC — whisper-local (azy.daily#421)
// ============================================================
// N'est atteint QUE si la soumission au service a échoué. Le service n'a alors jamais
// accepté le job : il ne rappellera pas, et chat.api attendrait indéfiniment (les jobs
// orphelins ne rendent pas les crédits, azy.daily#422). C'est donc à nous d'émettre
// l'échec, signé comme n'importe quel rappel du contrat #296.
const req = $('Valider la requête').first().json;
const entree = $input.first().json || {};

// Liste FERMÉE du contrat #296 : un code hors liste casserait l'aiguillage des clients.
const CODES = ['file_too_large', 'unsupported_format', 'audio_unreadable', 'audio_too_long',
  'provider_unavailable', 'provider_auth', 'audio_fetch_failed', 'internal_error'];

const nettoyer = s => String(s === undefined || s === null ? '' : s)
  .replace(/\s+/g, ' ').trim().slice(0, 300);

const analyser = c => {
  if (c && typeof c === 'object') return c;
  if (typeof c === 'string') { try { return JSON.parse(c); } catch (e) { return { message: c }; } }
  return {};
};

// Statut HTTP : présent si le service a répondu ; absent sur une erreur de transport, et
// n8n ne laisse alors qu'un message « NNN - … » ou un code réseau (cf. n8n : onError masque
// le statut). http_status reste null quand il n'y a eu AUCUNE réponse — on ne l'invente pas.
let statut = null;
let message = '';
if (typeof entree.statusCode === 'number') {
  statut = entree.statusCode;
  const corps = analyser(entree.body !== undefined ? entree.body : entree.data);
  message = corps.message || corps.error || `HTTP ${statut}`;
} else if (entree.error !== undefined) {
  const e = entree.error && typeof entree.error === 'object' ? entree.error : { message: String(entree.error) };
  const brut = String(e.message || '');
  const m = brut.match(/^\s*(\d{3})\s*-\s*([\s\S]*)$/);
  if (m) { statut = Number(m[1]); message = m[2]; } else { message = brut || String(e.code || 'transport'); }
} else {
  message = 'réponse inattendue du service whisper-local';
}

// provider_auth si le service exige un jeton que nous n'avons pas (ou plus) ; sinon le
// service est en panne, injoignable ou refuse la charge : provider_unavailable.
const code = (statut === 401 || statut === 403) ? 'provider_auth' : 'provider_unavailable';

const corps = {
  success: false,
  job_id: req.job_id,
  error: {
    code: CODES.includes(code) ? code : 'internal_error',
    http_status: statut,
    provider_message: nettoyer(`whisper-local n'a pas accepté le job — ${message}`),
  },
  meta: { provider: 'whisper-local', model: req.model },
};

return [{ json: { job_id: req.job_id, callback_url: req.callback_url, corps_json: JSON.stringify(corps) } }];
